            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background-color: #f4f4f9;
        }
        .container {
            background-color: white;
            padding: 30px;
            border-radius: 10px;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
            text-align: center;
        }
        h1 {
            color: #333;
        }
        #jokeDisplay {
            margin: 25px 0;
            padding: 15px;
            min-height: 50px; /* Ensures the box doesn't jump when content appears */
            font-size: 1.2em;
            border: 1px solid #ccc;
            border-radius: 5px;
            background-color: #e9f7ff;
        }
        button {
            padding: 10px 20px;
            font-size: 1em;
            color: white;
            background-color: #007bff;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: background-color 0.3s;
        }
        button:hover {
            background-color: #0056b3;
        }
    </style>
</head>
<body>

    <div class="container">
        <h1>😂 Joke Time! 😂</h1>

        <!-- This is where the joke will appear -->
        <div id="jokeDisplay">Click the button to get a laugh!</div>

        <!-- This button calls the JavaScript function when clicked -->
        <button onclick="displayRandomJoke()">Tell Me a Joke</button>
    </div>

    <script>
        // 1. Define the list of jokes
        const jokes = [
            "Why don't scientists trust atoms? Because they make up everything!",
            "What do you call a fish with no eyes? Fsh!",
            "Why did the scarecrow win an award? Because he was outstanding in his field!",
            "I told my wife she was drawing her eyebrows too high. She looked surprised."
        ];

        // 2. Function to select and display a random joke
        function displayRandomJoke() {
            // Generate a random index number between 0 (inclusive) and the length of the array (exclusive)
            const randomIndex = Math.floor(Math.random() * jokes.length);

            // Get the joke at that random index
            const randomJoke = jokes[randomIndex];

            // Find the HTML element where the joke should go
            const jokeElement = document.getElementById('jokeDisplay');

            // Update the content of that element
            jokeElement.textContent = randomJoke;
        }
    </script>

</body>
</html>
```

### How to Run This Code:

1.  **Save:** Copy the entire code block above and save it into a file named exactly `joke_generator.html`.
2.  **Open:** Double-click the saved file (`joke_generator.html`). It will open automatically in your web browser (Chrome, Firefox, Edge, etc.).
3.  **Test:** Click the "Tell Me a Joke" button, and a different joke will appear each time!

